package local.skyfamily;
import android.content.*;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import java.util.*;
public class HubActivity extends SeasonActivity {
 boolean assemblingHome=false;
 @Override void home(){assemblingHome=true;try{super.home();}finally{assemblingHome=false;}button("Uploads",()->uploadHub());}
 @Override void button(String title,Runnable action){if(assemblingHome&&(title.equals("Receive images with QR")||title.equals("Receive images / QR upload")||title.equals("Receive images and ebooks with QR")||title.equals("Uploaded images")||title.equals("Gallery and idle settings")||title.equals("Arcade and word games")))return;super.button(title,action);}
 @Override void settings(){page("Settings");section("Display");button("Themes and birthdays",()->visualSettings());button("Gallery and idle playback",()->gallerySettings());button("Rotate display",()->screenRotation());section("Connections");button(token.isEmpty()?"Connect Immich":"Immich library and sign-in",()->immich());button("Weather location",()->new PlanetaryPanel(this).search());button("Weather connection details",()->weatherDetails());button("Cast receiver / DLNA",()->castSetup());section("Files");button("Uploads / QR and device import",()->uploadHub());section("Device");button("Installed apps",()->apps());button("Android device settings",()->{try{startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}catch(Exception e){toast("Device settings unavailable");}});text("No extra web-panel URLs are required. Immich is configured when connecting; custom RSS stays in News. Existing saved values are retained, not erased.");}
 @Override void share(){uploadHub();}
 @Override void importBook(){uploadHub();}
 void uploadHub(){page("Uploads");text("One place to add images and books. Receive from a phone with QR, or choose a book already on this device.");section("Add files");button("Receive from phone / QR",()->uploadAddress());button("Import EPUB, PDF or TXT from device",()->HubActivity.super.importBook());section("Your files");button("Uploaded images",()->uploads());button("Bookshelf",()->bookshelf());button("Saved artwork projects",()->projectsEntry());text("QR accepts images, EPUB, PDF and UTF-8 TXT. Trusted LAN only; HTTP is unencrypted. Keep the QR screen open. Receiving stops on leaving or pausing, or after 15 minutes. Use trusted PDFs/books. Video transfer and editable-project upload are not supported; the saved-project link opens existing artwork.");}
 void uploadAddress(){ArrayList<InetAddress> addresses=new ArrayList<>();try{Enumeration<NetworkInterface> nets=NetworkInterface.getNetworkInterfaces();while(nets.hasMoreElements()){NetworkInterface net=nets.nextElement();if(!net.isUp()||net.isLoopback())continue;Enumeration<InetAddress> ips=net.getInetAddresses();while(ips.hasMoreElements()){InetAddress ip=ips.nextElement();if(ip instanceof Inet4Address&&ip.isSiteLocalAddress())addresses.add(ip);}}}catch(Exception e){toast("Cannot inspect local network");return;}if(addresses.size()==1){receive(addresses.get(0));return;}page("Uploads / choose network");if(addresses.isEmpty())text("Connect the frame and phone to a reachable trusted local network first. No private IPv4 address was found.");else{text("Choose the address reachable by your phone.");for(InetAddress address:addresses)button("Receive on "+address.getHostAddress(),()->receive(address));}button("Back to Uploads",()->uploadHub());}
 @Override void puzzle(){games(Math.max(0,Math.min(2,prefs.getInt("ui.games.tab",0))));}
 void games(int selected){page("Games");prefs.edit().putInt("ui.games.tab",selected).apply();LinearLayout tabs=new LinearLayout(this);body.addView(tabs);String[] labels={"All","Arcade","Words"};for(int i=0;i<labels.length;i++){final int tab=i;TextView control=new TextView(this);control.setText(labels[i]);control.setTextSize(17);control.setGravity(Gravity.CENTER);control.setTextColor(i==selected?bg:fg);control.setBackground(shape(i==selected?palette().accent:palette().surface,0,14));control.setSelected(i==selected);control.setFocusable(true);control.setContentDescription(labels[i]+(i==selected?" / selected tab":" / tab"));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(52),1);lp.setMargins(dp(4),0,dp(4),dp(14));tabs.addView(control,lp);control.setOnClickListener(v->games(tab));}text("Choose a card to play. Games run offline; scores and saved puzzle progress stay on this device.");ArrayList<String> names=new ArrayList<>(),descriptions=new ArrayList<>();ArrayList<Runnable> actions=new ArrayList<>();if(selected==0||selected==1){Collections.addAll(names,"Snake","Maze Chase","Falling Blocks","Pong","Drawing maze");Collections.addAll(descriptions,"Grow, turn and avoid your tail","Collect dots and dodge chasers","Rotate pieces and clear rows","Paddle match / first to seven","Trace a path through corridors");Collections.addAll(actions,()->playSnake(),()->play(1),()->play(2),()->play(3),()->play(0));}if(selected==0||selected==2){Collections.addAll(names,"Word maze","Mini crossword","Daily five-letter guess");Collections.addAll(descriptions,"Follow a word family to the exit","Fill the daily word grid","Six guesses / daily word");Collections.addAll(actions,()->maze(0),()->crossword(),()->guess());}int cols=getResources().getConfiguration().screenWidthDp>=950?3:2;LinearLayout row=null;for(int i=0;i<names.size();i++){if(i%cols==0){row=new LinearLayout(this);body.addView(row);}gameCard(row,names.get(i),descriptions.get(i),actions.get(i));}if(row!=null&&names.size()%cols!=0)for(int i=names.size()%cols;i<cols;i++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
 void gameCard(LinearLayout row,String title,String description,Runnable action){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(16),dp(16),dp(14));card.setBackground(shape(palette().surface,edge,18));card.addView(new ControlIcon(this,"Games"),new LinearLayout.LayoutParams(dp(28),dp(28)));TextView name=new TextView(this);name.setText(title);name.setTextColor(fg);name.setTextSize(20);name.setMaxLines(2);name.setPadding(0,dp(10),0,dp(6));card.addView(name);TextView detail=new TextView(this);detail.setText(description);detail.setTextColor(muted);detail.setTextSize(13);detail.setMaxLines(2);card.addView(detail);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(172),1);lp.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(card,lp);card.setContentDescription(title+". "+description);card.setFocusable(true);card.setOnClickListener(v->action.run());}
 @Override byte[] request(String address,String method,String json,String credential,int limit)throws Exception{URL url=new URL(address);if(!WeatherHttp.handles(url))return super.request(address,method,json,credential,limit);String stage=WeatherHttp.stage(url),key="weather.http."+stage;try{if(!method.equals("GET")||json!=null||!credential.isEmpty())throw new IOException("Weather requires a credential-free GET request");byte[] data=WeatherHttp.get(url,limit);save(key,"Open-Meteo "+stage+" succeeded / "+new Date());return data;}catch(Exception e){save(key,"Last attempt / "+new Date()+" / "+e.getMessage());throw e;}}
 void weatherDetails(){page("Weather connection details");for(String stage:new String[]{"forecast","location search"}){section(stage);String value=get("weather.http."+stage);text(value.isEmpty()?"No request recorded since this update.":value);}text("HTTP 403 means the request was denied. This screen cannot determine whether the provider or an intermediate network filter caused it. Immich credentials and placeholder URLs are unrelated. No proxy, HTTP downgrade, certificate bypass or fabricated forecast is used.");button("Retry saved-location forecast",()->new PlanetaryPanel(this).open(true));button("Search for a location",()->new PlanetaryPanel(this).search());text("The existing forecast cache remains active; failed refreshes show stale cached data only with an offline/stale label. Open-Meteo free access is for personal/non-commercial use and subject to provider limits.");}
}
